public class Main {
    public static void main(String[] args) throws Exception {
        var limit = new Window(2);
        System.out.println(limit.allow(0));
        System.out.println(limit.allow(1));
        System.out.println(limit.allow(2));
        System.out.println(limit.allow(1000));
    }
    static final class Window {
        final int limit; long bucket = -1; int count;
        Window(int limit) { this.limit = limit; }
        synchronized boolean allow(long nowMillis) {
            long current = nowMillis / 1000;
            if (current != bucket) { bucket = current; count = 0; }
            if (count >= limit) return false;
            count++; return true;
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        var a = new Account(1, 100);
        var b = new Account(2, 0);
        transfer(a,b,30);
        System.out.println(a.balance + ":" + b.balance);
    }
    static final class Account {
        final int id; long balance;
        Account(int id,long balance) { this.id=id; this.balance=balance; }
    }
    static void transfer(Account from,Account to,long amount) {
        if (from==to || from.id==to.id || amount<=0) throw new IllegalArgumentException();
        Account first=from.id<to.id?from:to, second=first==from?to:from;
        synchronized(first) { synchronized(second) {
            if (from.balance<amount) throw new IllegalStateException();
            from.balance-=amount; to.balance+=amount;
        }}
    }
}

